// Generated by `cargo xtask gen` from each tool's `--help`. Do not edit.

export const TOOL_HELP = {
	recab:
		"Manage system updates and rollback with two root slots (A/B)\n\nUsage: recab [OPTIONS] <COMMAND>\n\nCommands:\n  verify-installation  Verify both identical personalized initial roots and their boot payloads before finishing installation\n  update               Discover/download signed updates through Recipe; offline selection preserves prepared work\n  release              Verify/import one complete release set without changing the candidate\n  change               Apply Recipe software to the prepared inactive system; activation needs reboot\n  edit                 Edit configuration through a bounded temporary file, then apply to the inactive system\n  finalize             Validate, flush and seal the candidate, then publish its immutable boot entry\n  prepare              Synchronize the inactive slot in place, or reopen its existing preparation\n  discard              Explicitly abandon a matching preparation; does not restore an overwritten rollback\n  compare              Read the running system and the other one and say how alike they are; changes neither\n  inventory            Read a complete system inventory without changing it\n  status               Show detected A/B status\n  init                 Populate and seal both personalized A/B systems, or set up one mutable root\n  stage                Merge a verified release into the inactive preparation and finalize when conflict-free\n  set-next             Schedule one trial boot of the inactive slot (A or B)\n  commit               Commit currently booted slot as known-good and default\n  rollback             Configure next boot to previously known-good slot\n  trial                After startup: commit a healthy trial boot, or reboot into the known-good slot (run by the trial service on every boot)\n  health               Wait for startup to finish and report how it ended: the verdict a trial judges by (read-only; needs no A/B layout)\n  baseline             Capture the complete release inventory and account baseline before personalizing an extracted image (recsetup does this). Existing baselines are retained; a personalized generation cannot invent its original release\n  install-unit         Write recab's package contents into a tree: the trial service (systemd unit or OpenRC service), enabled, immutable runtime policy and executable-bound state/boot compatibility record\n  help                 Print this message or the help of the given subcommand(s)\n\nOptions:\n      --json            Print structured status, health, inventory, preparation and finalization; any command that fails prints one JSON error on stderr\n      --machine-events  Emit operation start/completion/failure JSON lines on stderr; stdout remains the command result\n      --actor <LABEL>   Who asked for this, recorded with a change: a short label such as \"person\" or \"agent:codex\". Front ends set it; it grants nothing\n  -h, --help            Print help\n  -V, --version         Print version\n\nCommon tasks:\n  recab status                    Show the running slot and next boot\n  recab status --root /mnt         Inspect an installed target\n  recab prepare                   Continue the running system in the inactive slot\n  recab change install ./pkg.rhai  Apply Recipe software to that preparation\n  recab edit etc/example --file X  Apply configuration to that preparation\n  recab update check              Discover signed updates through Recipe\n  recab update download           Cache the available release without changing X\n  recab finalize                  Validate, seal and publish that candidate\n  recab stage --from-media /media  Merge release media into the preparation\n  recab set-next B                 Schedule one trial boot of slot B\n  recab rollback                  Select the known-good slot for next boot\n\nA/B keeps two system copies. prepare synchronizes differences; finalize seals\nthe candidate; set-next selects a trial boot. stage merges a release and finalizes it when conflict-free. The trial service commits a healthy boot automatically.\nA and B support the same operations. Old development installs are read-only;\nuse compatible recovery media or a fresh installation. No automatic state upgrade.\nRead 'recab status' before choosing a slot. Add --json for structured status.",
	recinit:
		"Rootless initramfs builder for Linux\n\nUsage: recinit [OPTIONS] <COMMAND>\n\nCommands:\n  build-tiny     Build a tiny initramfs for live ISO boot\n  build-install  Build the busybox initramfs that boots an installed system (either distro)\n  help           Print this message or the help of the given subcommand(s)\n\nOptions:\n  -q, --quiet    Quiet mode (suppress progress messages)\n  -h, --help     Print help\n  -V, --version  Print version\n\nBuild an initramfs for an installed system:\n  recinit build-install --rootfs /mnt --busybox /path/to/busybox-static \\\n    --modules-dir /mnt/usr/lib/modules/<KERNEL-VERSION> --output initramfs-installed.img\n\nUse build-tiny for live ISO boot and build-install for an installed system.\nThe module tree must match the kernel you will boot. No root privileges needed.\nRun 'recinit <command> --help' for the required inputs.",
	reciso:
		'Create bootable UEFI ISOs from kernel + initramfs + rootfs\n\nUsage: reciso [OPTIONS] --kernel <KERNEL> --initrd <INITRD> --rootfs <ROOTFS> --label <LABEL> --output <OUTPUT> --build-uki <BUILD_UKIS>\n\nOptions:\n  -k, --kernel <KERNEL>\n          Path to kernel image (vmlinuz)\n\n  -i, --initrd <INITRD>\n          Path to initramfs image\n\n  -r, --rootfs <ROOTFS>\n          Path to rootfs image (EROFS)\n\n  -l, --label <LABEL>\n          ISO volume label\n\n  -o, --output <OUTPUT>\n          Output ISO path\n\n      --build-uki <BUILD_UKIS>\n          A boot entry\'s UKI, built inline (at least one). Format: "name:extra_cmdline:filename" Example: "Emergency:emergency:myos-emergency.efi"\n\n      --extra-file <EXTRA_FILES>\n          Add an extra file to the ISO. Format: "src:dst" Example: "/tmp/initramfs-installed.img:boot/initramfs-installed.img"\n\n      --overlay-image <OVERLAY_IMAGE>\n          Live overlay payload image (EROFS) to include\n\n      --os-name <OS_NAME>\n          OS name for the boot menu (e.g., "LevitateOS")\n\n      --os-id <OS_ID>\n          OS identifier (e.g., "levitateos")\n\n      --os-version <OS_VERSION>\n          OS version (e.g., "1.0")\n\n      --no-checksum\n          Skip checksum generation\n\n      --live-payload-layout <LAYOUT>\n          Layout for live payloads (only `iso-files`, the default)\n\n          Possible values:\n          - iso-files: Payloads are files under `live/` in the ISO filesystem\n          \n          [default: iso-files]\n\n      --systemd-boot <SYSTEMD_BOOT>\n          systemd-boot UEFI binary (default: the build host\'s)\n          \n          [default: /usr/lib/systemd/boot/efi/systemd-bootx64.efi]\n\n  -q, --quiet\n          Quiet mode - only print errors\n\n  -h, --help\n          Print help (see a summary with \'-h\')\n\n  -V, --version\n          Print version\n\nEXAMPLES:\n    # Boot entries, one UKI each (format: name:extra_cmdline:filename)\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO --build-uki \'Normal::myos.efi\' --build-uki \'Emergency:emergency:myos-emergency.efi\' --os-name MyOS --os-id myos --os-version 1.0 -o output.iso\n\n    # With live overlay image (EROFS)\n    reciso -k vmlinuz -i initramfs.img -r rootfs.erofs -l MYISO --build-uki \'Normal::myos.efi\' --overlay-image live-overlay.erofs -o output.iso\n\nREQUIREMENTS:\n    - systemd-boot (dnf install systemd-boot)\n    - xorriso (dnf install xorriso)\n    - mtools (dnf install mtools)\n    - ukify (dnf install systemd-ukify)',
	recpart:
		"Inspect disks, preview partition changes, and prepare an installation target\n\nUsage: recpart [OPTIONS] <COMMAND>\n\nCommands:\n  list-disks  Enumerate candidate target disks\n  inspect     Show a disk's partition table, partitions (filesystem, used space, mounts) and free gaps\n  plan        Preview partition changes without changing the disk\n  apply       Partition, format and mount the target (requires --confirm DESTROY)\n  help        Print this message or the help of the given subcommand(s)\n\nOptions:\n      --json     Emit machine-readable JSON (errors too, on stderr)\n  -h, --help     Print help\n  -V, --version  Print version\n\nStart here:\n  recpart list-disks\n  recpart inspect --disk /dev/sda\n  recpart plan --disk /dev/sda --mode ab\n  recpart apply --disk /dev/sda --mode ab --dry-run\n\nplan and --dry-run leave the disk unchanged. The default layout replaces all\npartitions; --layout supplies a custom layout. Read the plan before applying.\nRun 'recpart <command> --help' for options; add --json for scripts.",
	recchroot:
		"Enter chroot with proper bind mounts (like arch-chroot)\n\nUsage: recchroot <CHROOT_DIR> [COMMAND]...\n\nArguments:\n  <CHROOT_DIR>  Chroot directory (e.g., /mnt)\n  [COMMAND]...  Command to run (default: root's login shell in the target)\n\nOptions:\n  -h, --help     Print help\n  -V, --version  Print version\n\nExamples:\n  recchroot /mnt                 Open the target's root shell\n  recchroot /mnt passwd          Set the target's root password\n  recchroot /mnt /bin/sh -c 'cat /etc/os-release'\n\nRequires root. The target's /dev, /proc, /sys and /run are prepared for the\ncommand and cleaned up when it exits. Type 'exit' to leave the target shell.",
	recfstab:
		"Reads mounted filesystems under a root directory and outputs fstab entries naming each partition by PARTUUID (or filesystem UUID/LABEL, or PARTLABEL). PARTUUID is what the boot entries name the root by, and it survives the reformat an A/B update makes. Designed for system installation workflows where you need to generate /etc/fstab for a newly installed system.\n\nUsage: recfstab [OPTIONS] <ROOT>\n\nArguments:\n  <ROOT>\n          Root directory to scan for mounted filesystems (e.g., /mnt)\n\nOptions:\n  -L, --label\n          Use filesystem LABEL instead of PARTUUID for device identification\n\n  -U, --uuid\n          Use the filesystem UUID instead of PARTUUID\n\n  -p, --partuuid\n          Use partition UUID (PARTUUID), the default\n\n  -t, --partlabel\n          Use partition LABEL (PARTLABEL) instead of PARTUUID\n\n  -w, --write\n          Append the entries to <ROOT>/etc/fstab; refused (E036) when it already has entries for the same mount points\n\n      --replace\n          With --write: replace the fstab's entries for those mount points\n\n      --json\n          Print the entries, the fstab's current entries and warnings as JSON (errors go to stderr as JSON)\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version\n\nExamples:\n  recfstab /mnt                   Preview entries; leave fstab unchanged\n  recfstab /mnt --write           Append entries to /mnt/etc/fstab\n  recfstab /mnt --write --replace  Replace entries for these mount points\n\nMount the target's root, boot and other filesystems before generating entries.\nPlain stdout is valid fstab text, so 'recfstab /mnt > fstab.preview' also works.",
	recsetup:
		"Set up an extracted system: time zone, locale, keymap, hostname, accounts, boot and services\n\nUsage: recsetup [OPTIONS] <COMMAND>\n\nCommands:\n  inspect  Describe the target and list what can be chosen (time zones, locales, keymaps, ...)\n  plan     Check a request and print the exact commands, without running them\n  apply    Run the plan's commands in order, stopping at the first failure\n  help     Print this message or the help of the given subcommand(s)\n\nOptions:\n      --json     Emit machine-readable JSON (errors too, on stderr)\n  -h, --help     Print help\n  -V, --version  Print version\n\nStart here:\n  recsetup inspect --root /mnt\n  recsetup inspect --root /mnt --list timezones\n  recsetup plan --root /mnt --hostname my-pc --timezone Europe/Brussels\n  recsetup apply --root /mnt --hostname my-pc --timezone Europe/Brussels\n\ninspect and plan leave the target unchanged. apply runs the requested changes.\nFor users/passwords and boot options: recsetup apply --help",
	recstrap:
		"Extracts the EROFS rootfs image to a target directory. This is the pacstrap equivalent - it only extracts files; the live install docs describe the rest of the installation.\n\nUsage: recstrap [OPTIONS] <TARGET>\n\nArguments:\n  <TARGET>\n          Target directory (must be mounted, e.g., /mnt)\n\nOptions:\n      --rootfs <ROOTFS>\n          Rootfs image (auto-detected on the live ISO if not specified)\n\n  -f, --force\n          Shorthand for --allow-non-mountpoint --allow-nonempty\n\n      --allow-non-mountpoint\n          Allow a target directory that is not a mount point\n\n      --allow-nonempty\n          Allow a target directory that already contains files\n\n      --allow-host-root-fs\n          Allow extracting onto a filesystem the running system has mounted at / or another system directory such as /home (never implied by --force)\n\n  -q, --quiet\n          Quiet mode - minimal output for scripting\n\n  -c, --check\n          Check mode - run pre-flight validation only, don't extract\n\n      --json\n          Print progress as JSON lines on stdout (one event per line: start, progress, verify, done; with --check, one checked); errors go to stderr as JSON\n\n  -h, --help\n          Print help (see a summary with '-h')\n\n  -V, --version\n          Print version\n\nExamples:\n  recstrap /mnt --check       Check the target without extracting\n  recstrap /mnt               Extract the live ISO's system image\n  recstrap /mnt --rootfs /path/to/filesystem.erofs\n\nAfter extraction: preview fstab with 'recfstab /mnt', write it with\n'recfstab /mnt --write', then inspect configuration with 'recsetup inspect --root /mnt'.",
} as const;
